package ru.neverland.townycouncil.spending;
import java.util.*;import org.bukkit.*;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.PlayerQuitEvent;import org.bukkit.inventory.*;
import com.palmergames.bukkit.towny.TownyAPI;import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.*;import ru.neverland.townycouncil.*;import static ru.neverland.townycouncil.spending.SpendingPolicies.*;
/** Readable limits, explicit mayor confirmation, consistent back button and region-owned callbacks. */
public final class SpendingMenus implements Listener{
 private record View(UUID viewer,Inventory back,Map<Integer,Runnable> actions)implements InventoryHolder{public Inventory getInventory(){return null;}}
 private final NeverLandTownyCouncil plugin;private final CouncilService council;private final SpendingService service;private final Map<UUID,Quote> quotes=new HashMap<>();
 public SpendingMenus(NeverLandTownyCouncil plugin,CouncilService council,SpendingService service){this.plugin=plugin;this.council=council;this.service=service;}
 public boolean handles(String action){return Set.of("spending","limit","limit-confirm","limit-cancel").contains(action);}
 private Town own(Player p){if(!p.hasPermission("neverlandtownycouncil.use"))throw new IllegalArgumentException("Нет доступа к совету");var town=council.ownTown(p.getUniqueId());if(town==null)throw new IllegalArgumentException("Сначала вступите в город");return town;}
 public void command(CommandSender sender,String[] args){if(!(sender instanceof Player p))throw new IllegalArgumentException("Ограничения меняет мэр своего города в игре");var town=own(p);switch(args[0].toLowerCase(Locale.ROOT)){
  case "spending"->open(p,town,0);
  case "limit"->{if(args.length<4)throw new IllegalArgumentException("/council limit <житель> <одна покупка> <за 24 часа> [причина]; 0 — без ограничения");var resident=TownyAPI.getInstance().getResident(args[1]);if(resident==null)throw new IllegalArgumentException("Житель не найден");propose(p,town,resident.getUUID(),new Limits(parse(args[2]),parse(args[3])),args.length>4?String.join(" ",Arrays.copyOfRange(args,4,args.length)):"Ограничения расходов по решению мэра");}
  case "limit-confirm"->{if(args.length!=2)throw new IllegalArgumentException("Используйте кнопку подтверждения");confirm(p,UUID.fromString(args[1]));}
  case "limit-cancel"->{quotes.remove(p.getUniqueId());CouncilCommand.tell(p,"Изменение ограничений отменено");}
  default->throw new IllegalArgumentException("Неизвестное действие");}}
 private Inventory menu(Player p,String title,Map<Integer,Runnable> actions){var previous=p.getOpenInventory().getTopInventory();var back=previous.getHolder()instanceof View v?v.back():MenuStyle.previousMenu(p);var menu=MenuStyle.inventory(plugin,new View(p.getUniqueId(),back,actions),54,title);button(menu,actions,45,Material.ARROW,back==null?"Закрыть":"Назад",List.of(),()->MenuStyle.returnTo(p,back));return menu;}
 private static void button(Inventory menu,Map<Integer,Runnable> actions,int slot,Material icon,String title,List<String> lore,Runnable action){var item=new ItemStack(icon);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("&f"+title));meta.setLore(MenuStyle.loreStrings(lore));item.setItemMeta(meta);menu.setItem(slot,item);if(action!=null)actions.put(slot,action);}
 private static String name(UUID id){var r=TownyAPI.getInstance().getResident(id);return r==null?id.toString():r.getName();}
 public void open(Player p,Town town,int requested){if(!town.equals(own(p)))throw new IllegalArgumentException("Это настройки другого города");boolean mayor=council.mayEditAccess(p,town);var people=town.getResidents().stream().filter(r->mayor||r.getUUID().equals(p.getUniqueId())).sorted(Comparator.comparing(r->r.getName().toLowerCase(Locale.ROOT))).toList();int pages=Math.max(1,(people.size()+35)/36),page=Math.max(0,Math.min(requested,pages-1));var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Расходы жителей • "+(page+1)+"/"+pages,actions);
  for(int i=page*36;i<Math.min(people.size(),(page+1)*36);i++){var person=people.get(i);var limits=service.state().limits(town.getUUID(),person.getUUID());var lore=new ArrayList<>(List.of("&7Одна покупка: &f"+label(limits.operation()),"&7За последние 24 часа: &f"+label(limits.day()),"&7Учитываются и ожидающие оплаты.","&7Ограничение не выдаёт права на покупки."));lore.add(!service.available()?"&cПравила временно недоступны":mayor?"&fНажмите, чтобы настроить.":"&7Изменить может только мэр.");button(menu,actions,i-page*36,Material.PLAYER_HEAD,person.getName(),lore,mayor&&service.available()?()->edit(p,town,person.getUUID()):null);}
  button(menu,actions,49,Material.BOOK,"Как работают лимиты",List.of("&7Для покупок через казну NeverLand.","&7Личный кошелёк игрока не ограничивается.","&7Возвраты и автоматические платежи", "&7не расходуют личный лимит чиновника.","&7Уже принятые казной оплаты завершатся","&7по прежним условиям. Новое правило","&7действует на следующие запросы."),null);
  if(page>0)button(menu,actions,46,Material.ARROW,"Предыдущая страница",List.of(),()->open(p,town,page-1));if(page+1<pages)button(menu,actions,53,Material.ARROW,"Следующая страница",List.of(),()->open(p,town,page+1));p.openInventory(menu);
 }
 private void edit(Player p,Town town,UUID resident){if(!council.mayEditAccess(p,town))throw new IllegalArgumentException("Настройки доступны только мэру");var limits=service.state().limits(town.getUUID(),resident);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Расходы • "+name(resident),actions);button(menu,actions,20,Material.GOLD_INGOT,"Предел одной покупки",List.of("&7Сейчас: &f"+label(limits.operation()),"&fВыбрать новую сумму."),()->amounts(p,town,resident,true));button(menu,actions,24,Material.CLOCK,"Предел за 24 часа",List.of("&7Сейчас: &f"+label(limits.day()),"&7Скользящий период, а не календарный день.","&fВыбрать новую сумму."),()->amounts(p,town,resident,false));button(menu,actions,31,Material.WRITABLE_BOOK,"Свои суммы",List.of("&7/council limit "+name(resident)+" 1000 5000","&7Первая сумма — одна покупка,","&7вторая — за 24 часа; 0 снимает предел.","&7Перед сохранением покажем подтверждение."),null);p.openInventory(menu);}
 private void amounts(Player p,Town town,UUID resident,boolean single){var limits=service.state().limits(town.getUUID(),resident);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,single?"Предел одной покупки":"Предел за 24 часа",actions);int slot=19;for(long cents:new long[]{50000,100000,500000,1000000,0}){var next=single?new Limits(cents,limits.day()):new Limits(limits.operation(),cents);button(menu,actions,slot++,cents==0?Material.BARRIER:Material.GOLD_INGOT,label(cents),List.of("&7Житель: &f"+name(resident),"&7Перед сохранением будет подтверждение."),()->propose(p,town,resident,next,"Ограничения расходов по решению мэра"));}p.openInventory(menu);}
 private void propose(Player p,Town town,UUID resident,Limits limits,String reason){var quote=service.quote(p,town,resident,limits,reason);long now=System.currentTimeMillis();quotes.values().removeIf(q->now-q.createdAt()>60000);if(quotes.size()>=512&&!quotes.containsKey(p.getUniqueId()))throw new IllegalArgumentException("Много открытых подтверждений; попробуйте позже");quotes.put(p.getUniqueId(),quote);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Подтвердить лимиты",actions);button(menu,actions,13,Material.PAPER,quote.residentName(),List.of("&7Одна покупка: &f"+label(limits.operation()),"&7За последние 24 часа: &f"+label(limits.day()),"&7Причина: &f"+quote.reason(),"&7Это ограничение расходов, а не право покупки.","&7Принятые ранее платежи сохраняют условия.","&7Подтверждение действует 60 секунд."),null);button(menu,actions,29,Material.LIME_DYE,"Сохранить",List.of(),()->confirm(p,quote.id()));button(menu,actions,33,Material.GRAY_DYE,"Отмена",List.of(),()->{quotes.remove(p.getUniqueId(),quote);open(p,town,0);});p.openInventory(menu);}
 private void confirm(Player p,UUID id){var quote=quotes.get(p.getUniqueId());if(quote==null||!quote.id().equals(id))throw new IllegalArgumentException("Откройте подтверждение заново");quotes.remove(p.getUniqueId(),quote);var view=p.getOpenInventory().getTopInventory();var receipt=service.confirm(p,quote);CouncilCommand.tell(p,"Сохраняем ограничения расходов…");receipt.whenComplete((saved,error)->{if(!plugin.isEnabled()||SuiteState.frozen(plugin.getName()))return;SuiteScheduler.player(plugin,p,actor->{if(error!=null){Throwable cause=error;while(cause.getCause()!=null)cause=cause.getCause();CouncilCommand.tell(actor,"&cИзменение не подтверждено: "+cause.getMessage());return;}CouncilCommand.tell(actor,"&aОграничения сохранены");if(actor.getOpenInventory().getTopInventory()==view){var town=council.ownTown(actor.getUniqueId());if(town!=null)open(actor,town,0);}});});}
 @EventHandler public void click(InventoryClickEvent event){try(var guard=SuiteState.guard()){var top=event.getView().getTopInventory();if(!(top.getHolder()instanceof View view))return;event.setCancelled(true);if(SuiteState.frozen(plugin.getName())||!(event.getWhoClicked()instanceof Player p)||!p.getUniqueId().equals(view.viewer()))return;var action=view.actions().get(event.getRawSlot());if(action!=null)SuiteScheduler.entity(plugin,p,()->{if(p.getOpenInventory().getTopInventory()!=top)return;try{action.run();}catch(Exception error){CouncilCommand.tell(p,"&c"+error.getMessage());}});}}
 @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder()instanceof View)event.setCancelled(true);}@EventHandler public void quit(PlayerQuitEvent event){try(var guard=SuiteState.guard()){quotes.remove(event.getPlayer().getUniqueId());}}public void close(){quotes.clear();}
}
